state_adr={}
for r in recs:
    m=re.match(r'D-ADR(\d{4})',r['text'])
    if m and r.get('scope'): state_adr[m.group(1)]=r
idx=open('docs/decisions/index.md',encoding='utf8').read()
rows={}
for l in idx.splitlines():
    m=re.match(r'\|\s*([^|]+)\|\s*D-ADR(\d{4}):',l)
    if m: rows[m.group(2)]=l
print('Điểm 1 (tinh lại): đích có trong STATE (không tính index):')
for r in recs:
    rel=str(r.get('relation',''))
    m=re.fullmatch(r'supersedes:ADR(\d{4})',rel)
    if m and re.match(r'D-ADR',r['text']):
        t=m.group(1)
        print(f"  ADR{t}: state={'có' if t in state_adr else 'KHÔNG'}, index={'có' if t in rows else 'KHÔNG'}")
# Điểm 2: quan hệ trong câu chữ so với quan hệ máy đọc được
machine=set()
for r in recs:
    m=re.fullmatch(r'supersedes:ADR(\d{4})',str(r.get('relation','')))
    mm=re.match(r'D-ADR(\d{4})',r['text'])
    if m and mm: machine.add((mm.group(1),m.group(1)))
prose=set(); lost=[]
for k,l in rows.items():
    for t in re.findall(r'[Ss]upersede[sd]?\s+(?:của\s+)?(?:ADR|D-ADR)(\d{4})',l): prose.add((k,t))
    for by in re.findall(r'(?:đã\s+)?supersede\s+bởi\s+(?:ADR|D-ADR)(\d{4})',l): prose.add((by,k))
print('\nĐiểm 2: cặp (mới -> cũ) nêu trong câu chữ của index:',len(prose))
print('cặp máy đọc được (relation):',len(machine))
print('có trong câu chữ nhưng KHÔNG có relation:',sorted(prose-machine))
print('có relation nhưng không thấy trong câu chữ:',sorted(machine-prose))
sup_in_text=[k for k,l in rows.items() if re.search(r'supersed|thay thế|thay bằng|đảo',l,re.I)]
print('\nhàng index có chữ supersed/thay:',len(sup_in_text),'trên',len(rows))
EOF

