python3 - <<'EOF'
import json,os,re
def m(s): return re.sub(r'[\w.+-]+@[\w.-]+','<email>',str(s))
g=json.load(open(os.path.expanduser('~/.fgos/config.json')))
p=json.load(open('.fgos/config.json'))
print('=== llmAccounts (global) ===')
for scope,c in (('global',g),('project',p)):
    la=(c.get('runner') or {}).get('llmAccounts') or c.get('llmAccounts')
    if la: print('khai ở:',scope)
    for pool,accs in (la or {}).items():
        print('pool',pool)
        for a,av in accs.items():
            if isinstance(av,dict):
                safe={}
                for k,v in av.items():
                    if k in('credentialStore','credentialSources','credentialSource'):
                        safe[k]=json.loads(re.sub(r'[\w.+-]+@[\w.-]+','<email>',json.dumps(v)))
                    elif not any(t in k.lower() for t in('key','token','secret','password')):
                        safe[k]=m(v)[:80]
                print('  account',m(a),json.dumps(safe,ensure_ascii=False)[:400])
print('\n=== executors và invocations (project) ===')
ex=p['runner']['executors']
for name,e in ex.items():
    print('\n##',name,{k:m(e[k])[:60] for k in e if k in('kind','providerModel','provider','family','confinement') and not isinstance(e[k],(dict,list))})
    for inv in e.get('invocations',[]) or []:
        row={k:inv[k] for k in('id','via','adapter','cli','transport') if k in inv}
        conf=inv.get('confinement') or e.get('confinement')
        if conf: row['confine']=conf.get('backend') if isinstance(conf,dict) else conf
        cs=inv.get('credentialStore')
        if cs: row['credStore']=json.dumps(cs)[:90]
        env={k:('<set>' ) for k in (inv.get('env') or {})}
        if env: row['envKeys']=list(env)
        print('   ',m(json.dumps(row,ensure_ascii=False))[:300])
EOF

