    ap=os.path.join(d,'auth.json')
    if os.path.isfile(ap):
        try:
            j=json.load(open(ap,encoding='utf8')); print('   auth.json provider keys:',list(j.keys())[:6])
        except Exception: print('   auth.json không phải JSON')
EOF

