cd /tmp && python3 - <<'EOF'
import json,os,urllib.request,urllib.error
k=json.load(open(os.path.expanduser('~/.pi/accounts/thehive/auth.json')))['thehive']['key']
for path in ('/api/v3/models',):
    req=urllib.request.Request('https://api.thehive.ai'+path,headers={'Authorization':'Bearer '+k,'Accept':'application/json'})
    try:
        r=urllib.request.urlopen(req,timeout=20); print(path,'->',r.status)
    except urllib.error.HTTPError as e:
        body=e.read().decode('utf8','replace')[:160]
        print(path,'->',e.code,body)
    except Exception as e: print(path,'-> lỗi mạng',str(e)[:100])
EOF
echo "--- còn bản sao lưu khoá cũ nào do em tạo không:"; ls ~/.pi/accounts/thehive | tr '\n' ' '

